function dungeonVictory(){record('guardian','El guardián sin hora','El corazón de los relojes vuelve a latir. El templo queda restaurado.');say([['GUARDIÁN','Yo no detenía el tiempo. Impedía que saliera aquello que esperaba al otro lado.'],['NARRADOR','El templo despierta. En el mapa se encienden cinco lugares que aún no tienen nombre.']],()=>{state='complete';$('overlay').classList.remove('hidden');$('overlay').querySelector('.eyebrow').textContent='CAPÍTULO II · TEMPLO RESTAURADO';$('overlay').querySelector('h2').innerHTML='HORAS <i>ROTAS</i>';$('overlay').querySelector('p').textContent='El eco del templo señala la Aldea de Ceniza.';$('start').innerHTML='VIAJAR A LA ALDEA DE CENIZA →';$('start').onclick=startVillage})}
function objectiveVillage(){$('objective').textContent=village.won?'La Aldea de Ceniza ha recuperado su faro.':!village.emblem?'Habla con Alma. Busca el sigilo al este, en la Fractura.':!village.beacon?'Regresa al Presente. Activa el faro del centro de la aldea.':'Interactúa otra vez con el faro para escuchar el eco de la aldea.';$('echoes').textContent=`${village.emblem?1:0} / 1`}
