function villageVictory(){record('faro','El faro de las cenizas','El faro recuerda otra vez a sus habitantes. Más allá, las marismas siguen sin responder.');say([['ALMA',regionalStories.data.village.ending==='restore'?'Pondré el medallón junto a la ventana. No para esperar a mi padre. Para acordarme de que esta también es mi casa.':regionalStories.data.village.ending==='release'?'Lo enterraste bajo el fresno. Hoy he visto una hoja nueva. Mi padre habría dicho que ya era hora.':'La casa de mi padre vuelve a tener luz. Sigue vacía. Esta noche, por primera vez, encenderé la lámpara de todas formas.'],['NARRADOR','Al norte, las marismas se retuercen como una herida. El viaje aún no ha terminado.']],()=>{state='complete';$('overlay').classList.remove('hidden');$('overlay').querySelector('.eyebrow').textContent='CAPÍTULO III · ALDEA DE CENIZA';$('overlay').querySelector('h2').innerHTML='EL FARO <i>RECUERDA</i>';$('overlay').querySelector('p').textContent='Nueva región completada. Las restantes regiones de la campaña aún están en desarrollo.';$('start').textContent='VIAJAR A LAS MARISMAS →';$('start').onclick=startMarsh})}
