function startMarsh(){grantMilestone("village-heart");marsh.enter(player);village.active=false;dungeon.active=false;combat.hp=combat.maxHp;combat.invuln=0;combatUI();state='playing';keys.clear();$('overlay').classList.add('hidden');$('zone').textContent='MARISMAS DEL OLVIDO';setRealm(false);objectiveMarsh();checkpoint=snapshot();storeSnapshot(checkpoint);record('marismas','Las Marismas del Olvido','Más allá de la aldea, el agua oculta un sendero que solo existe en la hora equivocada.');say([['NARRADOR','La niebla huele a hierro y a recuerdos mojados. Ni los pájaros se atreven a dar la hora.'],['VOZ DEL RELOJ','Una cartógrafa espera cerca del viejo dique. Busca el paso y la campana hundida.']])}
function marshVictory(){record('campana-marismas','La campana sumergida','La ciénaga recuperó su voz. Más allá se adivina una ciudad sumergida.');say([['NERA',regionalStories.data.marsh.ending==='restore'?'Has devuelto el mapa. He dejado una esquina en blanco para los caminos que aún no conocemos.':regionalStories.data.marsh.ending==='release'?'El agua se llevó el mapa. Hoy he trazado la costa con una rama. Nadie puede borrar el primer intento.':'No he recuperado el mapa que perdí. He encontrado un camino que nadie dibujó antes. Supongo que también cuenta.'],['NARRADOR','Del agua emerge el perfil de una ciudad. Una puerta se abre en el malecón.']],()=>{state='complete';$('overlay').classList.remove('hidden');$('overlay').querySelector('.eyebrow').textContent='CAPÍTULO IV · MARISMAS DEL OLVIDO';$('overlay').querySelector('h2').innerHTML='VOCES <i>SUMERGIDAS</i>';$('overlay').querySelector('p').textContent='Capítulo IV completado. Ciudad Sumergida y capítulos posteriores siguen pendientes.';$('start').textContent='VIAJAR A LA CIUDAD SUMERGIDA →';$('start').onclick=startCity})}
function objectiveSanctuary(){$('objective').textContent=sanctuary.won?'El destino de Veyra ya está escrito.':sanctuary.room===0?!sanctuary.ash?'Encuentra la ceniza primordial en la Fractura.':!sanctuary.aligned?'Restaura el péndulo en el Presente.':'Cruza al Archivo de los Ausentes.':sanctuary.room===1?!sanctuary.memory?'Recupera la memoria de Aster en la Fractura.':!sanctuary.open?'Abre el sello en el Presente.':'Cruza el umbral final.':sanctuary.boss.hp>0?'Derrota al Segundero: vulnerable en la Fractura.':'Activa el corazón del último segundo.';$('echoes').textContent=`${Number(sanctuary.ash)+Number(sanctuary.memory)} / 2`}
function startSanctuary(){grantMilestone("fortress-memory");sanctuary.enter(player);fortress.active=false;city.active=false;marsh.active=false;village.active=false;dungeon.active=false;combat.hp=combat.maxHp;combat.invuln=0;combatUI();state='playing';keys.clear();$('overlay').classList.add('hidden');$('zone').textContent='SANTUARIO DEL ÚLTIMO SEGUNDO';setRealm(false);objectiveSanctuary();checkpoint=snapshot();storeSnapshot(checkpoint);record('santuario','El Santuario del Último Segundo','La hija de Aster aguarda detrás de la última campanada.');say([['NARRADOR','Tras el séptimo umbral, una hora entera cabe dentro de una lágrima.'],['LA VOZ DEL RELOJ','Recupera el principio, escucha la última memoria y decide qué debe continuar.']])}
function sanctuaryVictory(){sanctuary.ending=narrative.choice==='keep'?'keep':'release';const keeping=sanctuary.ending==='keep';record('final-veyra',keeping?'El archivo de los ausentes':'El tiempo vuelve a correr',keeping?'La memoria de quienes faltan permanece en un santuario fuera del tiempo.':'Las horas vuelven a correr y los recuerdos, por fin, pueden cambiar.');say(keeping?[['LA HIJA DE ASTER','Padre me prometió un amanecer. No necesitaba que durase para siempre. Solo quería verlo con él.'],['MARA','Los ausentes tendrán un lugar. No una jaula, sino una memoria.'],['NARRADOR','Las campanas callan. En Veyra, nadie vuelve a ser borrado sin dejar un nombre.']]:[['LA HIJA DE ASTER','No tengo miedo de la mañana, aunque no llegue a verla. Me asusta más que nadie pueda tener otra.'],['MARA','El recuerdo duele. Pero mañana será posible.'],['NARRADOR','Las siete campanas suenan y Veyra despierta. El tiempo avanza por primera vez en siglos.']],()=>{state='complete';$('overlay').classList.remove('hidden');$('overlay').querySelector('.eyebrow').textContent='EIDOLON 404 · FIN DE LA CAMPAÑA';$('overlay').querySelector('h2').textContent=keeping?'EL ARCHIVO VIVE':'AMANECE EN VEYRA';$('overlay').querySelector('p').textContent=keeping?'Final: Custodiar los recuerdos. Las horas regresan, y sus ausentes conservan un lugar.':'Final: Liberar las horas. El reino recibe un mañana incierto y libre.';$('start').textContent='NUEVA PARTIDA';$('start').onclick=restart;storeSnapshot(snapshot())})}
function updateSanctuary(dt){$('clock').textContent=`${String(Math.floor(elapsed/60)).padStart(2,'0')}:${String(Math.floor(elapsed%60)).padStart(2,'0')}`;let dx=Number(keys.has('ArrowRight')||keys.has('KeyD'))-Number(keys.has('ArrowLeft')||keys.has('KeyA')),dy=Number(keys.has('ArrowDown')||keys.has('KeyS'))-Number(keys.has('ArrowUp')||keys.has('KeyW'));if(dx||dy){const l=Math.hypot(dx,dy),v=(combat.dodge>0?170:74)*dt;dx=dx/l*v;dy=dy/l*v;if(sanctuary.canStand(player.x+dx,player.y))player.x+=dx;if(sanctuary.canStand(player.x,player.y+dy))player.y+=dy;player.walk+=dt*10;player.dir=Math.abs(dx)>Math.abs(dy)?dx>0?1:3:dy>0?2:0}combat.invuln=Math.max(0,combat.invuln-dt);combat.dodge=Math.max(0,combat.dodge-dt);combat.dodgeCooldown=Math.max(0,combat.dodgeCooldown-dt);sanctuary.update(dt,player,combat);combatUI();if(combat.hp<=0){sanctuary.active=false;state='defeated';$('overlay').classList.remove('hidden');$('overlay').querySelector('h2').textContent='HAS CAÍDO';$('overlay').querySelector('p').textContent='El último segundo sigue esperando.';$('start').textContent='VOLVER AL PUNTO DE CONTROL';$('start').onclick=recover}}
function objectiveFortress(){$('objective').textContent=fortress.won?'La sexta hora vuelve a sonar.':fortress.room===0?!fortress.gear?'Habla con Seren y encuentra el engranaje en la Fractura.':!fortress.bridge?'Activa el eje en el Presente para restaurar el puente.':'Avanza a la Galería de las Agujas.':fortress.room===1?!fortress.key?'Recupera la llave de la sexta hora en la Fractura.':!fortress.lock?'Desbloquea el sello en el Presente.':'Entra en la Cámara del Maestro.':fortress.boss.hp>0?'Derrota a Aster, vulnerable en la Fractura.':'Activa el reloj de la sexta hora.';$('echoes').textContent=`${fortress.gear?1:0} / 1`}
function startFortress(){grantMilestone("city-memory");fortress.enter(player);city.active=false;marsh.active=false;village.active=false;dungeon.active=false;combat.hp=combat.maxHp;combat.invuln=0;combatUI();state='playing';keys.clear();$('overlay').classList.add('hidden');$('zone').textContent='FORTALEZA DE LOS RELOJEROS';setRealm(false);objectiveFortress();checkpoint=snapshot();storeSnapshot(checkpoint);record('fortaleza','La Fortaleza de los Relojeros','La sexta hora está aprisionada en engranajes y juramentos.');say([['NARRADOR','Los engranajes no marcan el tiempo: giran alrededor de algo encerrado.'],['LA VOZ DEL RELOJ','Escucha a la última relojera. El maestro conocía el precio de detener una hora.']])}
function fortressVictory(){record('confesion-aster','La confesión de Aster','El maestro detuvo el tiempo para impedir que su hija desapareciera; el Santuario guarda el último secreto.');say([['ASTER','Le prometí que veríamos amanecer. Cuando comprendí que no llegaría viva a la mañana, obligué al mundo entero a esperarla.'],['NARRADOR','Aster no pide perdón. Baja la cabeza y se aparta del mecanismo. Tras él, una puerta late como un corazón cansado.']],()=>startSanctuary())}
function updateFortress(dt){$('clock').textContent=`${String(Math.floor(elapsed/60)).padStart(2,'0')}:${String(Math.floor(elapsed%60)).padStart(2,'0')}`;let dx=Number(keys.has('ArrowRight')||keys.has('KeyD'))-Number(keys.has('ArrowLeft')||keys.has('KeyA')),dy=Number(keys.has('ArrowDown')||keys.has('KeyS'))-Number(keys.has('ArrowUp')||keys.has('KeyW'));if(dx||dy){const l=Math.hypot(dx,dy),v=(combat.dodge>0?170:74)*dt;dx=dx/l*v;dy=dy/l*v;if(fortress.canStand(player.x+dx,player.y))player.x+=dx;if(fortress.canStand(player.x,player.y+dy))player.y+=dy;player.walk+=dt*10;player.dir=Math.abs(dx)>Math.abs(dy)?dx>0?1:3:dy>0?2:0}combat.invuln=Math.max(0,combat.invuln-dt);combat.dodge=Math.max(0,combat.dodge-dt);combat.dodgeCooldown=Math.max(0,combat.dodgeCooldown-dt);fortress.update(dt,player,combat);combatUI();if(combat.hp<=0){fortress.active=false;state='defeated';$('overlay').classList.remove('hidden');$('overlay').querySelector('h2').textContent='HAS CAÍDO';$('overlay').querySelector('p').textContent='Los relojeros aguardan tu regreso.';$('start').textContent='VOLVER AL PUNTO DE CONTROL';$('start').onclick=recover}if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('toast').classList.remove('show')}}
function objectiveCity(){$('objective').textContent=city.won?'El reloj sumergido vuelve a marcar las horas.':city.room===0?!city.valve?'Habla con el Cartógrafo. Recupera la válvula en la Fractura.':!city.drained?'Regresa al Presente y activa la estación de bombeo.':'Cruza hasta la cripta al sureste.':city.room===1?!city.sigil?'Encuentra el sigilo oculto en la Fractura.':!city.ward?'Restaura el pedestal en el Presente.':'Cruza la puerta al abismo.':city.boss.hp>0?'Derrota al Leviatán de Piedra: solo es vulnerable en la Fractura.':'Activa el reloj del extremo noreste.';$('echoes').textContent=`${city.valve?1:0} / 1`}
