const archiveIcons={ECOS:'◈',FRAGMENTO:'⌛',ALTAR:'✧',LLAVE:'⚿',PLACAS:'◫',SELLO:'⬡',ENGRANAJE:'⚙',SEXTA:'Ⅵ',CENIZA:'✶',MEMORIA:'✦',DESTINO:'☼',RUEDA:'◉',COMPUERTAS:'≋',SIGILO:'◇',RELOJ:'◷',LÁMPARA:'♧',PASARELA:'⌁',CAMPANA:'♜',FARO:'♧',VITALIDAD:'♥',JURAMENTO:'✧',BOSQUE:'♧',TEMPLO:'♜',ALDEA:'⌂',MARISMAS:'≋',CIUDAD:'♜',FORTALEZA:'⚙',SANTUARIO:'✦'};
let archiveKind='inventory';
function archiveIcon(title){const found=Object.keys(archiveIcons).find(k=>title.startsWith(k));return archiveIcons[found]||'◇'}
function enrichArchive(kind){
 archiveKind=kind;
 $('tabInventory').setAttribute('aria-selected',String(kind==='inventory'));
 $('tabMap').setAttribute('aria-selected',String(kind==='map'));
 if(kind==='inventory'){
  for(const secret of FOREST_SECRETS){const article=document.createElement('article');const h=document.createElement('h3');h.textContent='◇ '+secret.title.toUpperCase();const d=document.createElement('p');d.textContent=secrets.found.has(secret.id)?'OBTENIDO · '+secret.description:'PENDIENTE · Secreto opcional del Bosque de las Campanas';article.append(h,d);$('panelBody').append(article)}
  for(const item of REWARD_DEFS){const article=document.createElement('article');const h=document.createElement('h3');h.textContent='✦ '+item.name.toUpperCase();const d=document.createElement('p');d.textContent=rewards.unlocked.has(item.id)?'OBTENIDO · '+item.description:'PENDIENTE · '+item.description;article.append(h,d);$('panelBody').append(article)}
 }
 const cards=[...$('panelBody').querySelectorAll('article')];
 let completed=0;
 cards.forEach((el,i)=>{
   const head=el.querySelector('h3'),detail=el.querySelector('p');if(!head||!detail)return;
   const status=detail.textContent;
   const blocked=/pendiente|sin decidir|sin restaurar|sin decidir|cerradas|no descubierta|desconocida|inaccesible|aún inaccesible|dormida|sin posesión|sin recuperar|no descubierto/i.test(status);
   const done=/recuperad|restaurad|liberad|complet|custodiad|horas liberadas|obtenid|despertad/i.test(status);
   if(done)completed++;
   el.classList.add('archiveCard');el.classList.toggle('locked',blocked);el.classList.toggle('complete',done);
   const symbol=document.createElement('span');symbol.className='archiveIcon';symbol.setAttribute('aria-hidden','true');symbol.textContent=archiveIcon(head.textContent);
   const copy=document.createElement('div');copy.className='archiveCopy';copy.append(head,detail);
   el.replaceChildren(symbol,copy);
   if(kind==='map'){el.style.setProperty('--archive-index',String(i+1).padStart(2,'0'))}
 });
 $('panelSummary').textContent=kind==='map'?'CARTOGRAFÍA · 7 REGIONES · Las ubicaciones se revelan según tu progreso.':'RELIQUIAS Y MEMORIAS · '+cards.length+' registros · '+completed+' logros recuperados';
}
const oldTogglePanel=togglePanel;
togglePanel=function(kind){
 const wasOpen=!$('adventurePanel').classList.contains('hidden');
 if(wasOpen&&kind!==archiveKind){$('adventurePanel').classList.add('hidden');state='playing';oldTogglePanel(kind);enrichArchive(kind);return}
 oldTogglePanel(kind);
 if(!$('adventurePanel').classList.contains('hidden'))enrichArchive(kind);
};
$('tabInventory').addEventListener('click',()=>{if(archiveKind!=='inventory')togglePanel('inventory')});
$('tabMap').addEventListener('click',()=>{if(archiveKind!=='map')togglePanel('map')});
const oldToggleJournal=toggleJournal;
toggleJournal=function(){oldToggleJournal();if(state==='journal'){
 $('journalSearch').value='';filterJournal('');
}};
function filterJournal(value){let visible=0;const q=value.trim().toLocaleLowerCase('es');const list=[...$('journalEntries').querySelectorAll('article')];
 for(const el of list){const match=el.textContent.toLocaleLowerCase('es').includes(q);el.hidden=!match;if(match)visible++}
 $('journalCount').textContent=visible+' / '+list.length+' recuerdos';
}
$('journalSearch').addEventListener('input',e=>filterJournal(e.target.value));
// Restore focus after closing a modal with its explicit close button.
$('panelClose').onclick=()=>{togglePanel(archiveKind);$('inventoryBtn').focus()};
$('journalClose').addEventListener('click',()=>{$('journalBtn').focus()});

